1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  createRoutineSchema,
5	  createRoutineTriggerSchema,
6	  rotateRoutineTriggerSecretSchema,
7	  runRoutineSchema,
8	  updateRoutineSchema,
9	  updateRoutineTriggerSchema,
10	} from "@paperclipai/shared";
11	import { trackRoutineCreated } from "@paperclipai/shared/telemetry";
12	import { validate } from "../middleware/validate.js";
13	import { accessService, logActivity, routineService } from "../services/index.js";
14	import { assertCompanyAccess, getActorInfo } from "./authz.js";
15	import { forbidden, unauthorized } from "../errors.js";
16	import { getTelemetryClient } from "../telemetry.js";
17	import type { PluginWorkerManager } from "../services/plugin-worker-manager.js";
18	
19	export function routineRoutes(
20	  db: Db,
21	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
22	) {
23	  const router = Router();
24	  const svc = routineService(db, {
25	    pluginWorkerManager: options.pluginWorkerManager,
26	  });
27	  const access = accessService(db);
28	
29	  async function assertBoardCanAssignTasks(req: Request, companyId: string) {
30	    assertCompanyAccess(req, companyId);
31	    if (req.actor.type !== "board") return;
32	    if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return;
33	    const allowed = await access.canUser(companyId, req.actor.userId, "tasks:assign");
34	    if (!allowed) {
35	      throw forbidden("Missing permission: tasks:assign");
36	    }
37	  }
38	
39	  function assertCanManageCompanyRoutine(req: Request, companyId: string, assigneeAgentId?: string | null) {
40	    assertCompanyAccess(req, companyId);
41	    if (req.actor.type === "board") return;
42	    if (req.actor.type !== "agent" || !req.actor.agentId) throw unauthorized();
43	    if (assigneeAgentId !== req.actor.agentId) {
44	      throw forbidden("Agents can only manage routines assigned to themselves");
45	    }
46	  }
47	
48	  async function assertCanManageExistingRoutine(req: Request, routineId: string) {
49	    const routine = await svc.get(routineId);
50	    if (!routine) return null;
51	    assertCompanyAccess(req, routine.companyId);
52	    if (req.actor.type === "board") return routine;
53	    if (req.actor.type !== "agent" || !req.actor.agentId) throw unauthorized();
54	    if (routine.assigneeAgentId !== req.actor.agentId) {
55	      throw forbidden("Agents can only manage routines assigned to themselves");
56	    }
57	    return routine;
58	  }
59	
60	  router.get("/companies/:companyId/routines", async (req, res) => {
61	    const companyId = req.params.companyId as string;
62	    assertCompanyAccess(req, companyId);
63	    const result = await svc.list(companyId);
64	    res.json(result);
65	  });
66	
67	  router.post("/companies/:companyId/routines", validate(createRoutineSchema), async (req, res) => {
68	    const companyId = req.params.companyId as string;
69	    await assertBoardCanAssignTasks(req, companyId);
70	    assertCanManageCompanyRoutine(req, companyId, req.body.assigneeAgentId);
71	    const created = await svc.create(companyId, req.body, {
72	      agentId: req.actor.type === "agent" ? req.actor.agentId : null,
73	      userId: req.actor.type === "board" ? req.actor.userId ?? "board" : null,
74	    });
75	    const actor = getActorInfo(req);
76	    await logActivity(db, {
77	      companyId,
78	      actorType: actor.actorType,
79	      actorId: actor.actorId,
80	      agentId: actor.agentId,
81	      runId: actor.runId,
82	      action: "routine.created",
83	      entityType: "routine",
84	      entityId: created.id,
85	      details: { title: created.title, assigneeAgentId: created.assigneeAgentId },
86	    });
87	    const telemetryClient = getTelemetryClient();
88	    if (telemetryClient) {
89	      trackRoutineCreated(telemetryClient);
90	    }
91	    res.status(201).json(created);
92	  });
93	
94	  router.get("/routines/:id", async (req, res) => {
95	    const detail = await svc.getDetail(req.params.id as string);
96	    if (!detail) {
97	      res.status(404).json({ error: "Routine not found" });
98	      return;
99	    }
100	    assertCompanyAccess(req, detail.companyId);
101	    res.json(detail);
102	  });
103	
104	  router.patch("/routines/:id", validate(updateRoutineSchema), async (req, res) => {
105	    const routine = await assertCanManageExistingRoutine(req, req.params.id as string);
106	    if (!routine) {
107	      res.status(404).json({ error: "Routine not found" });
108	      return;
109	    }
110	    const assigneeWillChange =
111	      req.body.assigneeAgentId !== undefined &&
112	      req.body.assigneeAgentId !== routine.assigneeAgentId;
113	    if (assigneeWillChange) {
114	      await assertBoardCanAssignTasks(req, routine.companyId);
115	    }
116	    const statusWillActivate =
117	      req.body.status !== undefined &&
118	      req.body.status === "active" &&
119	      routine.status !== "active";
120	    if (statusWillActivate) {
121	      await assertBoardCanAssignTasks(req, routine.companyId);
122	    }
123	    if (
124	      req.actor.type === "agent" &&
125	      req.body.assigneeAgentId !== undefined &&
126	      req.body.assigneeAgentId !== req.actor.agentId
127	    ) {
128	      throw forbidden("Agents can only assign routines to themselves");
129	    }
130	    const updated = await svc.update(routine.id, req.body, {
131	      agentId: req.actor.type === "agent" ? req.actor.agentId : null,
132	      userId: req.actor.type === "board" ? req.actor.userId ?? "board" : null,
133	    });
134	    const actor = getActorInfo(req);
135	    await logActivity(db, {
136	      companyId: routine.companyId,
137	      actorType: actor.actorType,
138	      actorId: actor.actorId,
139	      agentId: actor.agentId,
140	      runId: actor.runId,
141	      action: "routine.updated",
142	      entityType: "routine",
143	      entityId: routine.id,
144	      details: { title: updated?.title ?? routine.title },
145	    });
146	    res.json(updated);
147	  });
148	
149	  router.get("/routines/:id/runs", async (req, res) => {
150	    const routine = await svc.get(req.params.id as string);
151	    if (!routine) {
152	      res.status(404).json({ error: "Routine not found" });
153	      return;
154	    }
155	    assertCompanyAccess(req, routine.companyId);
156	    const limit = Number(req.query.limit ?? 50);
157	    const result = await svc.listRuns(routine.id, Number.isFinite(limit) ? limit : 50);
158	    res.json(result);
159	  });
160	
161	  router.post("/routines/:id/triggers", validate(createRoutineTriggerSchema), async (req, res) => {
162	    const routine = await assertCanManageExistingRoutine(req, req.params.id as string);
163	    if (!routine) {
164	      res.status(404).json({ error: "Routine not found" });
165	      return;
166	    }
167	    await assertBoardCanAssignTasks(req, routine.companyId);
168	    const created = await svc.createTrigger(routine.id, req.body, {
169	      agentId: req.actor.type === "agent" ? req.actor.agentId : null,
170	      userId: req.actor.type === "board" ? req.actor.userId ?? "board" : null,
171	    });
172	    const actor = getActorInfo(req);
173	    await logActivity(db, {
174	      companyId: routine.companyId,
175	      actorType: actor.actorType,
176	      actorId: actor.actorId,
177	      agentId: actor.agentId,
178	      runId: actor.runId,
179	      action: "routine.trigger_created",
180	      entityType: "routine_trigger",
181	      entityId: created.trigger.id,
182	      details: { routineId: routine.id, kind: created.trigger.kind },
183	    });
184	    res.status(201).json(created);
185	  });
186	
187	  router.patch("/routine-triggers/:id", validate(updateRoutineTriggerSchema), async (req, res) => {
188	    const trigger = await svc.getTrigger(req.params.id as string);
189	    if (!trigger) {
190	      res.status(404).json({ error: "Routine trigger not found" });
191	      return;
192	    }
193	    const routine = await assertCanManageExistingRoutine(req, trigger.routineId);
194	    if (!routine) {
195	      res.status(404).json({ error: "Routine not found" });
196	      return;
197	    }
198	    await assertBoardCanAssignTasks(req, routine.companyId);
199	    const updated = await svc.updateTrigger(trigger.id, req.body, {
200	      agentId: req.actor.type === "agent" ? req.actor.agentId : null,
201	      userId: req.actor.type === "board" ? req.actor.userId ?? "board" : null,
202	    });
203	    const actor = getActorInfo(req);
204	    await logActivity(db, {
205	      companyId: routine.companyId,
206	      actorType: actor.actorType,
207	      actorId: actor.actorId,
208	      agentId: actor.agentId,
209	      runId: actor.runId,
210	      action: "routine.trigger_updated",
211	      entityType: "routine_trigger",
212	      entityId: trigger.id,
213	      details: { routineId: routine.id, kind: updated?.kind ?? trigger.kind },
214	    });
215	    res.json(updated);
216	  });
217	
218	  router.delete("/routine-triggers/:id", async (req, res) => {
219	    const trigger = await svc.getTrigger(req.params.id as string);
220	    if (!trigger) {
221	      res.status(404).json({ error: "Routine trigger not found" });
222	      return;
223	    }
224	    const routine = await assertCanManageExistingRoutine(req, trigger.routineId);
225	    if (!routine) {
226	      res.status(404).json({ error: "Routine not found" });
227	      return;
228	    }
229	    await svc.deleteTrigger(trigger.id);
230	    const actor = getActorInfo(req);
231	    await logActivity(db, {
232	      companyId: routine.companyId,
233	      actorType: actor.actorType,
234	      actorId: actor.actorId,
235	      agentId: actor.agentId,
236	      runId: actor.runId,
237	      action: "routine.trigger_deleted",
238	      entityType: "routine_trigger",
239	      entityId: trigger.id,
240	      details: { routineId: routine.id, kind: trigger.kind },
241	    });
242	    res.status(204).end();
243	  });
244	
245	  router.post(
246	    "/routine-triggers/:id/rotate-secret",
247	    validate(rotateRoutineTriggerSecretSchema),
248	    async (req, res) => {
249	      const trigger = await svc.getTrigger(req.params.id as string);
250	      if (!trigger) {
251	        res.status(404).json({ error: "Routine trigger not found" });
252	        return;
253	      }
254	      const routine = await assertCanManageExistingRoutine(req, trigger.routineId);
255	      if (!routine) {
256	        res.status(404).json({ error: "Routine not found" });
257	        return;
258	      }
259	      const rotated = await svc.rotateTriggerSecret(trigger.id, {
260	        agentId: req.actor.type === "agent" ? req.actor.agentId : null,
261	        userId: req.actor.type === "board" ? req.actor.userId ?? "board" : null,
262	      });
263	      const actor = getActorInfo(req);
264	      await logActivity(db, {
265	        companyId: routine.companyId,
266	        actorType: actor.actorType,
267	        actorId: actor.actorId,
268	        agentId: actor.agentId,
269	        runId: actor.runId,
270	        action: "routine.trigger_secret_rotated",
271	        entityType: "routine_trigger",
272	        entityId: trigger.id,
273	        details: { routineId: routine.id },
274	      });
275	      res.json(rotated);
276	    },
277	  );
278	
279	  router.post("/routines/:id/run", validate(runRoutineSchema), async (req, res) => {
280	    const routine = await assertCanManageExistingRoutine(req, req.params.id as string);
281	    if (!routine) {
282	      res.status(404).json({ error: "Routine not found" });
283	      return;
284	    }
285	    await assertBoardCanAssignTasks(req, routine.companyId);
286	    const run = await svc.runRoutine(routine.id, req.body, {
287	      agentId: req.actor.type === "agent" ? req.actor.agentId : null,
288	      userId: req.actor.type === "board" ? req.actor.userId ?? null : null,
289	    });
290	    const actor = getActorInfo(req);
291	    await logActivity(db, {
292	      companyId: routine.companyId,
293	      actorType: actor.actorType,
294	      actorId: actor.actorId,
295	      agentId: actor.agentId,
296	      runId: actor.runId,
297	      action: "routine.run_triggered",
298	      entityType: "routine_run",
299	      entityId: run.id,
300	      details: { routineId: routine.id, source: run.source, status: run.status },
301	    });
302	    res.status(202).json(run);
303	  });
304	
305	  router.post("/routine-triggers/public/:publicId/fire", async (req, res) => {
306	    const result = await svc.firePublicTrigger(req.params.publicId as string, {
307	      authorizationHeader: req.header("authorization"),
308	      signatureHeader: req.header("x-paperclip-signature"),
309	      hubSignatureHeader: req.header("x-hub-signature-256"),
310	      timestampHeader: req.header("x-paperclip-timestamp"),
311	      idempotencyKey: req.header("idempotency-key"),
312	      rawBody: (req as { rawBody?: Buffer }).rawBody ?? null,
313	      payload: typeof req.body === "object" && req.body !== null ? req.body as Record<string, unknown> : null,
314	    });
315	    res.status(202).json(result);
316	  });
317	
318	  return router;
319	}
